import type { StopReason, TraceEntry } from '@faultlab/engine';

/**
 * The Worker message protocol (CP5, ADR-0022). Both directions are plain, structured-cloneable
 * data, validated on receipt: a malformed or unknown message is a protocol violation, never
 * guessed at. Every message carries the protocol id and the run it belongs to.
 *
 * Executable code never crosses this boundary: experiments travel as ExperimentSpec JSON and are
 * resolved against the registry inside the Worker.
 */
export const WORKER_PROTOCOL = 'faultlab-worker/1';

/** Unique per run; generated by the client. Messages of any other run are ignored. */
export type RunId = string;

/** How trace chunks travel: structured clone of the entries, or UTF-8 JSON in a transferred buffer. */
export type ChunkEncoding = 'clone' | 'json';

export interface RunOptions {
  readonly encoding: ChunkEncoding;
  /** At most this many entries per chunk (a single huge step is split across chunks). */
  readonly chunkMaxEntries: number;
  /** Wall-clock budget per execution slice in ms; checked between simulation steps only. */
  readonly sliceBudgetMs: number;
  /** At most this many simulation steps per slice. */
  readonly sliceMaxSteps: number;
  /** Chunks the Worker may send before it must wait for credit (flow control). */
  readonly initialCredits: number;
  /** Keep an engine snapshot every this many steps (0 = none). */
  readonly keyframeSteps: number;
}

export const DEFAULT_RUN_OPTIONS: RunOptions = Object.freeze({
  encoding: 'clone',
  chunkMaxEntries: 2048,
  sliceBudgetMs: 8,
  sliceMaxSteps: 100_000,
  initialCredits: 4,
  keyframeSteps: 1024,
});

/** Execution states as the Worker reports them. */
export type WorkerState = 'ready' | 'running' | 'paused' | 'completed' | 'stopped';

// ── commands: main thread → Worker ─────────────────────────────────────────────────────────

interface Base {
  readonly protocol: typeof WORKER_PROTOCOL;
  readonly runId: RunId;
}

export type Command =
  | (Base & { readonly type: 'load'; readonly spec: unknown; readonly options: RunOptions })
  /** Run until the experiment ends, or until paused or stopped. */
  | (Base & { readonly type: 'run' })
  /** Cooperative pause: takes effect at the next step boundary (between slices). */
  | (Base & { readonly type: 'pause' })
  /** Execute exactly `steps` more steps, then pause. */
  | (Base & { readonly type: 'step'; readonly steps: number })
  /** Normal stop: end the run deliberately; produced entries are still delivered. */
  | (Base & { readonly type: 'stop' })
  /** Flow control: the client applied chunks and allows this many more. */
  | (Base & { readonly type: 'credit'; readonly chunks: number })
  /** Engine snapshot after `atStep` completed steps (null: the current position). */
  | (Base & { readonly type: 'snapshot'; readonly requestId: number; readonly atStep: number | null });

// ── events: Worker → main thread ───────────────────────────────────────────────────────────

export interface StatusFields {
  readonly state: WorkerState;
  readonly stepsCompleted: number;
  readonly now: number;
  readonly traceLength: number;
  readonly pendingEvents: number;
  readonly stopReason: StopReason | null;
  /** True while execution waits for credit (the consumer is behind). */
  readonly throttled: boolean;
}

export type ChunkPayload =
  | { readonly encoding: 'clone'; readonly entries: readonly TraceEntry[] }
  | { readonly encoding: 'json'; readonly data: ArrayBuffer };

export type WorkerEvent =
  | (Base & { readonly type: 'loaded'; readonly engineVersion: string; readonly protocolName: string; readonly protocolVersion: string })
  /** Entries [from, to) of the trace. `seq` counts chunks from 0 without gaps. */
  | (Base & { readonly type: 'chunk'; readonly seq: number; readonly from: number; readonly to: number } & ChunkPayload)
  | (Base & { readonly type: 'status' } & StatusFields)
  /** The run ended (all its entries were sent before this). `fingerprint` covers the whole trace. */
  | (Base & {
      readonly type: 'finished';
      readonly state: 'completed' | 'stopped';
      readonly stopReason: StopReason | null;
      readonly stepsCompleted: number;
      readonly traceLength: number;
      readonly fingerprint: string;
      /** Wall-clock measurements of the Worker itself (never part of the trace). */
      readonly metrics: WorkerMetrics;
    })
  | (Base & { readonly type: 'snapshot'; readonly requestId: number; readonly step: number; readonly snapshot: unknown })
  | (Base & { readonly type: 'error'; readonly code: ErrorCode; readonly message: string; readonly requestId?: number });

export interface WorkerMetrics {
  /** Milliseconds executing simulation steps. */
  readonly executeMs: number;
  /** Milliseconds preparing and posting chunks (JSON encoding, or the structured clone inside postMessage). */
  readonly flushMs: number;
  readonly slices: number;
  readonly chunks: number;
  /** Total bytes of JSON-encoded chunks (0 with the clone encoding). */
  readonly bytes: number;
  /** Most trace entries the Worker held at once (sent entries are released): its memory bound. */
  readonly maxRetainedEntries: number;
}

export type ErrorCode = 'invalid-message' | 'invalid-spec' | 'invalid-state' | 'engine-error';

// ── validation ─────────────────────────────────────────────────────────────────────────────

export class ContractError extends Error {
  override name = 'ContractError';
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isNat = (v: unknown): v is number => Number.isSafeInteger(v) && (v as number) >= 0;
const fail = (message: string): never => {
  throw new ContractError(message);
};
const WORKER_STATES: readonly string[] = ['ready', 'running', 'paused', 'completed', 'stopped'];

function base(raw: unknown): Record<string, unknown> {
  if (!isObject(raw)) fail('message must be an object');
  const m = raw as Record<string, unknown>;
  if (m['protocol'] !== WORKER_PROTOCOL) fail(`unsupported protocol ${String(m['protocol'])} (expected ${WORKER_PROTOCOL})`);
  if (typeof m['runId'] !== 'string' || m['runId'] === '') fail('runId must be a non-empty string');
  if (typeof m['type'] !== 'string') fail('type must be a string');
  return m;
}

export function parseRunOptions(raw: unknown): RunOptions {
  if (!isObject(raw)) return fail('options must be an object');
  const o = raw;
  if (o['encoding'] !== 'clone' && o['encoding'] !== 'json') fail('options.encoding must be "clone" or "json"');
  for (const key of ['chunkMaxEntries', 'sliceMaxSteps', 'initialCredits'] as const) if (!isNat(o[key]) || (o[key] as number) < 1) fail(`options.${key} must be a positive integer`);
  if (typeof o['sliceBudgetMs'] !== 'number' || !((o['sliceBudgetMs'] as number) > 0)) fail('options.sliceBudgetMs must be a positive number');
  if (!isNat(o['keyframeSteps'])) fail('options.keyframeSteps must be a non-negative integer');
  return o as unknown as RunOptions;
}

/** Validate a command received by the Worker. */
export function parseCommand(raw: unknown): Command {
  const m = base(raw);
  switch (m['type']) {
    case 'load':
      parseRunOptions(m['options']);
      break;
    case 'run':
    case 'pause':
    case 'stop':
      break;
    case 'step':
      if (!isNat(m['steps']) || (m['steps'] as number) < 1) fail('step.steps must be a positive integer');
      break;
    case 'credit':
      if (!isNat(m['chunks']) || (m['chunks'] as number) < 1) fail('credit.chunks must be a positive integer');
      break;
    case 'snapshot':
      if (!isNat(m['requestId'])) fail('snapshot.requestId must be a non-negative integer');
      if (m['atStep'] !== null && !isNat(m['atStep'])) fail('snapshot.atStep must be null or a non-negative integer');
      break;
    default:
      fail(`unknown command ${String(m['type'])}`);
  }
  return m as unknown as Command;
}

function status(m: Record<string, unknown>): void {
  if (!WORKER_STATES.includes(m['state'] as string)) fail('status.state is invalid');
  for (const key of ['stepsCompleted', 'now', 'traceLength', 'pendingEvents'] as const) if (!isNat(m[key])) fail(`status.${key} must be a non-negative integer`);
  if (m['stopReason'] !== null && typeof m['stopReason'] !== 'string') fail('status.stopReason must be null or a string');
  if (typeof m['throttled'] !== 'boolean') fail('status.throttled must be a boolean');
}

/**
 * Validate an event received by the client. Chunk CONTENTS (the entries) come from the trusted
 * Worker runtime and are not schema-checked entry by entry; their positions are (seq, from, to,
 * and each entry's own index), which is what ordering and completeness depend on.
 */
export function parseEvent(raw: unknown): WorkerEvent {
  const m = base(raw);
  switch (m['type']) {
    case 'loaded':
      for (const key of ['engineVersion', 'protocolName', 'protocolVersion'] as const) if (typeof m[key] !== 'string') fail(`loaded.${key} must be a string`);
      break;
    case 'chunk':
      if (!isNat(m['seq']) || !isNat(m['from']) || !isNat(m['to']) || (m['to'] as number) <= (m['from'] as number)) fail('chunk needs seq and a non-empty range from < to');
      if (m['encoding'] === 'clone') {
        if (!Array.isArray(m['entries']) || m['entries'].length !== (m['to'] as number) - (m['from'] as number)) fail('chunk.entries must hold exactly to − from entries');
      } else if (m['encoding'] === 'json') {
        if (!(m['data'] instanceof ArrayBuffer)) fail('chunk.data must be an ArrayBuffer');
      } else fail('chunk.encoding must be "clone" or "json"');
      break;
    case 'status':
      status(m);
      break;
    case 'finished':
      if (m['state'] !== 'completed' && m['state'] !== 'stopped') fail('finished.state must be completed or stopped');
      if (!isNat(m['stepsCompleted']) || !isNat(m['traceLength']) || typeof m['fingerprint'] !== 'string') fail('finished needs stepsCompleted, traceLength and fingerprint');
      if (!isObject(m['metrics'])) fail('finished.metrics must be an object');
      break;
    case 'snapshot':
      if (!isNat(m['requestId']) || !isNat(m['step']) || !isObject(m['snapshot'])) fail('snapshot needs requestId, step and a snapshot object');
      break;
    case 'error':
      if (typeof m['code'] !== 'string' || typeof m['message'] !== 'string') fail('error needs code and message');
      break;
    default:
      fail(`unknown event ${String(m['type'])}`);
  }
  return m as unknown as WorkerEvent;
}

/** Decode a chunk's entries (both encodings), check their positions, and deep-freeze them. */
export function decodeChunk(chunk: Extract<WorkerEvent, { type: 'chunk' }>, decoder: { decode(data: ArrayBuffer): string }): readonly TraceEntry[] {
  const entries = chunk.encoding === 'clone' ? chunk.entries : (JSON.parse(decoder.decode(chunk.data)) as unknown);
  if (!Array.isArray(entries) || entries.length !== chunk.to - chunk.from) throw new ContractError(`chunk ${chunk.seq} holds ${Array.isArray(entries) ? entries.length : 'no'} entries for [${chunk.from}, ${chunk.to})`);
  entries.forEach((e: unknown, i) => {
    if (!isObject(e) || e['index'] !== chunk.from + i || typeof e['kind'] !== 'string') throw new ContractError(`chunk ${chunk.seq}: entry ${i} is not entry #${chunk.from + i}`);
  });
  return deepFreeze(entries) as readonly TraceEntry[];
}

function deepFreeze<T>(value: T): T {
  if (typeof value === 'object' && value !== null && !Object.isFrozen(value)) {
    Object.freeze(value);
    for (const child of Object.values(value)) deepFreeze(child);
  }
  return value;
}
